public class LinkedListTour {
    static class Node {
        int value;
        Node next;
        Node(int value, Node next) { this.value = value; this.next = next; }
    }

    static Node fromArray(int... values) {
        Node head = null;
        for (int i = values.length - 1; i >= 0; i--) head = new Node(values[i], head);  // insert at head
        return head;
    }

    static String show(Node head) {
        StringBuilder sb = new StringBuilder();
        for (Node n = head; n != null; n = n.next) sb.append(n.value).append(" -> ");
        return sb.append("null").toString();
    }

    static Node reverse(Node head) {
        Node prev = null;
        while (head != null) {
            Node next = head.next;
            head.next = prev;
            prev = head;
            head = next;
        }
        return prev;
    }

    // Slow moves 1 step, fast moves 2: when fast reaches the end, slow is in the middle
    static Node middle(Node head) {
        Node slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }
        return slow;
    }

    static Node mergeSorted(Node a, Node b) {
        Node dummy = new Node(0, null), tail = dummy;
        while (a != null && b != null) {
            if (a.value <= b.value) { tail.next = a; a = a.next; }
            else { tail.next = b; b = b.next; }
            tail = tail.next;
        }
        tail.next = (a != null) ? a : b;
        return dummy.next;
    }

    public static void main(String[] args) {
        Node list = fromArray(3, 8, 12, 20, 25);
        System.out.println("list:     " + show(list));
        System.out.println("middle:   " + middle(list).value);
        list = reverse(list);
        System.out.println("reversed: " + show(list));
        Node merged = mergeSorted(fromArray(1, 4, 9), fromArray(2, 3, 10, 11));
        System.out.println("merged:   " + show(merged));
    }
}

public class SinglyLinkedList {
    static class Node {
        String value;
        Node next;
        Node(String value, Node next) { this.value = value; this.next = next; }
    }

    Node head;

    void addFirst(String value) { head = new Node(value, head); }

    void addLast(String value) {
        Node fresh = new Node(value, null);
        if (head == null) { head = fresh; return; }
        Node n = head;
        while (n.next != null) n = n.next;      // walk to the last node: O(n)
        n.next = fresh;
    }

    void insertAfter(Node node, String value) {
        Node fresh = new Node(value, node.next);   // 1) point at the rest first
        node.next = fresh;                          // 2) then link it in
    }

    boolean remove(String value) {
        if (head == null) return false;
        if (head.value.equals(value)) { head = head.next; return true; }   // deleting the head
        Node prev = head;
        while (prev.next != null && !prev.next.value.equals(value)) prev = prev.next;
        if (prev.next == null) return false;    // not found
        prev.next = prev.next.next;             // skip over the node
        return true;
    }

    Node find(String value) {
        for (Node n = head; n != null; n = n.next) if (n.value.equals(value)) return n;
        return null;
    }

    public String toString() {
        StringBuilder sb = new StringBuilder();
        for (Node n = head; n != null; n = n.next) sb.append(n.value).append(" -> ");
        return sb.append("null").toString();
    }

    public static void main(String[] args) {
        SinglyLinkedList playlist = new SinglyLinkedList();
        System.out.println("empty:            " + playlist + ", remove(x) = " + playlist.remove("x"));
        playlist.addLast("intro");
        playlist.addLast("verse");
        playlist.addLast("outro");
        System.out.println("addLast x3:       " + playlist);
        playlist.addFirst("count-in");
        System.out.println("addFirst:         " + playlist);
        playlist.insertAfter(playlist.find("verse"), "chorus");
        System.out.println("insert after verse: " + playlist);
        System.out.println("remove(count-in) = " + playlist.remove("count-in") + ": " + playlist);
        System.out.println("remove(chorus)   = " + playlist.remove("chorus") + ": " + playlist);
        System.out.println("remove(bridge)   = " + playlist.remove("bridge") + ": " + playlist);
    }
}

