import java.util.HashMap;
import java.util.Map;

public class DoublyLinkedList {
    static class Node {
        String value;
        Node prev, next;
        Node(String value) { this.value = value; }
    }

    final Node head = new Node("HEAD"), tail = new Node("TAIL");   // sentinels
    final Map<String, Node> index = new HashMap<>();

    DoublyLinkedList() { head.next = tail; tail.prev = head; }

    void insertBefore(Node node, String value) {
        Node fresh = new Node(value);
        fresh.prev = node.prev;
        fresh.next = node;
        node.prev.next = fresh;
        node.prev = fresh;
        index.put(value, fresh);
    }

    void addFirst(String value) { insertBefore(head.next, value); }
    void addLast(String value) { insertBefore(tail, value); }

    void unlink(Node node) {                 // O(1): no search needed
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    void touch(String value) {               // move to the front (most recently used)
        Node node = index.get(value);
        unlink(node);
        addFirst(value);
    }

    String forward() {
        StringBuilder sb = new StringBuilder();
        for (Node n = head.next; n != tail; n = n.next) sb.append(n.value).append(n.next != tail ? " <-> " : "");
        return sb.toString();
    }

    String backward() {
        StringBuilder sb = new StringBuilder();
        for (Node n = tail.prev; n != head; n = n.prev) sb.append(n.value).append(n.prev != head ? " <-> " : "");
        return sb.toString();
    }

    public static void main(String[] args) {
        DoublyLinkedList recent = new DoublyLinkedList();
        for (String file : new String[]{"a.txt", "b.txt", "c.txt", "d.txt"}) recent.addLast(file);
        System.out.println("forward:  " + recent.forward());
        System.out.println("backward: " + recent.backward());
        recent.unlink(recent.index.get("b.txt"));
        System.out.println("unlink b: " + recent.forward());
        recent.touch("d.txt");
        System.out.println("open d:   " + recent.forward());
        recent.touch("a.txt");
        System.out.println("open a:   " + recent.forward());
        System.out.println("least recently used: " + recent.tail.prev.value);
    }
}

