        self.value = value
        self.prev = self.next = None


class DoublyLinkedList:
    def __init__(self):
        self.head, self.tail = Node("HEAD"), Node("TAIL")  # sentinels
        self.head.next, self.tail.prev = self.tail, self.head
        self.index = {}

    def insert_before(self, node, value):
        fresh = Node(value)
        fresh.prev, fresh.next = node.prev, node
        node.prev.next = fresh
        node.prev = fresh
        self.index[value] = fresh

    def add_first(self, value):
        self.insert_before(self.head.next, value)

    def add_last(self, value):
        self.insert_before(self.tail, value)

    def unlink(self, node):  # O(1): no search needed
        node.prev.next = node.next
        node.next.prev = node.prev

    def touch(self, value):  # move to the front (most recently used)
        self.unlink(self.index[value])
        self.add_first(value)

    def forward(self):
        out, n = [], self.head.next
        while n is not self.tail:
            out.append(n.value)
            n = n.next
        return " <-> ".join(out)

    def backward(self):
        out, n = [], self.tail.prev
        while n is not self.head:
            out.append(n.value)
            n = n.prev
        return " <-> ".join(out)


