public class CycleDetection {
    static class Node {
        int value;
        Node next;
        Node(int value) { this.value = value; }
    }

    // Builds 1 -> 2 -> ... -> n; if loopTo > 0, the last node points back to node loopTo
    static Node build(int n, int loopTo) {
        Node[] nodes = new Node[n + 1];
        for (int i = 1; i <= n; i++) nodes[i] = new Node(i);
        for (int i = 1; i < n; i++) nodes[i].next = nodes[i + 1];
        if (loopTo > 0) nodes[n].next = nodes[loopTo];
        return nodes[1];
    }

    static Node meetingPoint(Node head) {
        Node slow = head, fast = head;
        int step = 0;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            step++;
            System.out.println("  step " + step + ": tortoise at " + slow.value + ", hare at " + fast.value);
            if (slow == fast) return slow;
        }
        if (fast != null) System.out.println("  hare reached the last node: no cycle");
        else System.out.println("  hare ran off the end: no cycle");
        return null;
    }

    public static void main(String[] args) {
        System.out.println("list 1..5 without a cycle:");
        meetingPoint(build(5, 0));

        System.out.println("list 1..7 where 7 points back to 3:");
        Node head = build(7, 3);
        Node meet = meetingPoint(head);
        System.out.println("  met at node " + meet.value);

        Node a = head, b = meet;          // one from the head, one from the meeting point
        while (a != b) { a = a.next; b = b.next; }
        System.out.println("cycle starts at node " + a.value);

        int length = 1;
        for (Node n = a.next; n != a; n = n.next) length++;
        System.out.println("cycle length " + length);
    }
}

public class ListReversal {
    static class Node {
        int value;
        Node next;
        Node(int value, Node next) { this.value = value; this.next = next; }
    }

    static String show(Node n) {
        StringBuilder sb = new StringBuilder();
        for (; n != null; n = n.next) sb.append(n.value).append(" -> ");
        return sb.append("null").toString();
    }

    static Node reverseIterative(Node head) {
        Node prev = null, current = head;
        while (current != null) {
            Node next = current.next;   // 1) save the rest
            current.next = prev;        // 2) flip one arrow
            prev = current;             // 3) grow the reversed part
            current = next;             // 4) move on
            System.out.println("  reversed: " + show(prev) + " | rest: " + show(current));
        }
        return prev;                    // the new head
    }

    static Node reverseRecursive(Node head) {
        if (head == null || head.next == null) return head;   // base case
        Node newHead = reverseRecursive(head.next);
        head.next.next = head;          // the node after head now points back to it
        head.next = null;
        return newHead;
    }

    // Reverse positions left..right (1-based)
    static Node reverseBetween(Node head, int left, int right) {
        Node dummy = new Node(0, head), before = dummy;
        for (int i = 1; i < left; i++) before = before.next;
        Node first = before.next;
        for (int i = 0; i < right - left; i++) {
            Node moved = first.next;     // take the node after 'first'...
            first.next = moved.next;
            moved.next = before.next;    // ...and put it at the front of the range
            before.next = moved;
        }
        return dummy.next;
    }

    public static void main(String[] args) {
        Node head = new Node(1, new Node(2, new Node(3, new Node(4, null))));
        System.out.println("start: " + show(head));
        head = reverseIterative(head);
        System.out.println("iterative result: " + show(head));
        head = reverseRecursive(head);
        System.out.println("recursive (back again): " + show(head));
        head = new Node(1, new Node(2, new Node(3, new Node(4, new Node(5, null)))));
        System.out.println("reverse positions 2..4 of 1..5: " + show(reverseBetween(head, 2, 4)));
    }
}

public class MergeOperations {
    static class Node {
        int value;
        Node next;
        Node(int value, Node next) { this.value = value; this.next = next; }
    }

    static Node of(int... values) {
        Node head = null;
        for (int i = values.length - 1; i >= 0; i--) head = new Node(values[i], head);
        return head;
    }

    static String show(Node n) {
        StringBuilder sb = new StringBuilder("[");
        for (; n != null; n = n.next) sb.append(n.value).append(n.next != null ? ", " : "");
        return sb.append("]").toString();
    }

    static Node merge(Node a, Node b) {
        Node dummy = new Node(0, null), tail = dummy;
        while (a != null && b != null) {
            if (a.value <= b.value) { tail.next = a; a = a.next; }   // <= keeps ties stable
            else { tail.next = b; b = b.next; }
            tail = tail.next;
        }
        tail.next = (a != null) ? a : b;    // attach whatever is left
        return dummy.next;
    }

    static Node mergeSort(Node head) {
        if (head == null || head.next == null) return head;
        Node slow = head, fast = head.next;
        while (fast != null && fast.next != null) { slow = slow.next; fast = fast.next.next; }
        Node second = slow.next;
        slow.next = null;                   // cut the list in two
        return merge(mergeSort(head), mergeSort(second));
    }

    public static void main(String[] args) {
        Node a = of(1, 4, 7, 10), b = of(2, 3, 8);
        System.out.println(show(a) + " + " + show(b));
        System.out.println("merged: " + show(merge(a, b)));

        Node unsorted = of(38, 27, 43, 3, 9, 82, 10);
        System.out.println("merge sort " + show(unsorted));
        System.out.println("        -> " + show(mergeSort(unsorted)));

        Node[] lists = {of(5, 15), of(1, 20, 30), of(10, 12)};
        Node all = null;
        for (Node list : lists) all = merge(all, list);
        System.out.println("three lists merged: " + show(all));
    }
}

